Component({
  selector: 'taon-detached-window',
  standalone: true,
  imports: [
    CommonModule,
    CdkDrag,
    CdkDragHandle,
    MatIconModule,
    MatButtonModule,
    MatTooltipModule,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  styles: [
    `
      :host {
        display: block;
      }

      .taon-detached-window {
        position: absolute;

        top: 80px;
        left: 80px;

        width: min(900px, calc(100vw - 80px));
        height: min(700px, calc(100vh - 80px));

        min-width: 320px;
        min-height: 200px;

        display: flex;
        flex-direction: column;

        background: var(--mat-sys-surface, white);

        color: var(--mat-sys-on-surface, black);

        border: 1px solid var(--mat-sys-outline-variant, #ccc);

        border-radius: 8px;

        box-shadow: 0 8px 30px rgba(0, 0, 0, 0.2);

        overflow: hidden;

        resize: both;
      }

      .taon-detached-window-header {
        height: 40px;

        flex: 0 0 40px;

        display: flex;
        align-items: center;

        padding-left: 12px;

        border-bottom: 1px solid var(--mat-sys-outline-variant, #ccc);

        user-select: none;
      }

      .taon-detached-window-drag-handle {
        flex: 1;

        height: 100%;

        display: flex;
        align-items: center;

        cursor: move;

        overflow: hidden;
      }

      .taon-detached-window-title {
        overflow: hidden;

        white-space: nowrap;

        text-overflow: ellipsis;

        font-weight: 500;
      }

      .taon-detached-window-actions {
        display: flex;

        align-items: center;

        padding-right: 4px;
      }

      .taon-detached-window-body {
        flex: 1;

        min-height: 0;

        overflow: auto;
      }

      .taon-detached-window-component-host {
        display: block;

        min-height: 100%;
      }
    `,
  ],
  template: `
    <div
      class="taon-detached-window"
      cdkDrag
      [style.z-index]="window.zIndex"
      (pointerdown)="focus()">
      <header class="taon-detached-window-header">
        <div
          class="taon-detached-window-drag-handle"
          cdkDragHandle>
          <span class="taon-detached-window-title">
            {{ window.title }}
          </span>
        </div>

        <div class="taon-detached-window-actions">
          <button
            mat-icon-button
            type="button"
            matTooltip="Close"
            (click)="close()">
            <mat-icon> close </mat-icon>
          </button>
        </div>
      </header>

      <main class="taon-detached-window-body">
        <div
          #componentHost
          class="taon-detached-window-component-host"></div>
      </main>
    </div>
  `,
})

